window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e80088ba3601a5fc"]={"versions": [{"id": "FIG-e80088ba3601a5fc", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Methodikdiagramm zur Modellierungsstrategie in AUTOSAR Adaptive Platform (TPS MachineConfiguration). Das Diagramm visualisiert die vollständige Ableitung des Design-Modells in das Konfigurations-Modell, bei der die eigenständige Design-Repräsentation zugunsten des abgeleiteten Konfigurationsartefakts entfällt bzw. ersetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Design</strong>: Als Wolkenform dargestellte Modellebene/Entität, die mit einem roten, gestrichelten Kreuz markiert ist.\n</li><li><strong>Configration</strong>: Als Wolkenform dargestellte Zielmodellebene/Konfigurationsentität.\n</li><li><strong>Derive</strong>: Breiter, bogenförmiger Richtungspfeil von der Entität „Design“ zur Entität „Configration“, beschriftet entlang des Pfeilbogens mit „Derive“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Unidirektionaler Transformationsprozess („Derive“): Die Inhalte des Designmodells werden vollständig in das Konfigurationsmodell überführt. Das Durchstreichen des Ausgangsmodells verdeutlicht, dass nach Durchführung des Ableitungsschritts kein separates Design-Artefakt weitergepflegt wird, sondern dieses vollständig in der Zielkonfiguration aufgeht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodischer Hinweis für Modellierungs- und Tooling-Workflows in AUTOSAR Adaptive: Werkzeuge und Entwickler müssen sicherstellen, dass bei dieser Strategie sämtliche designrelevanten Informationen lückenlos in die Konfigurationsmodellierung übertragen werden, da keine parallele Pflege von Design- und Konfigurationsartefakten vorgesehen ist.</p>"}, {"id": "FIG-168ebc0d6cef6bc2", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Methodikdiagramm zur Modellierungsstrategie in AUTOSAR Adaptive Platform (TPS MachineConfiguration). Das Diagramm visualisiert die vollständige Ableitung des Design-Modells in das Konfigurations-Modell, bei der die eigenständige Design-Repräsentation zugunsten des abgeleiteten Konfigurationsartefakts entfällt bzw. ersetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Design</strong>: Als Wolkenform dargestellte Modellebene/Entität, die mit einem halbtransparenten roten Balkenkreuz überdeckt ist.\n</li><li><strong>Configuration</strong>: Als Wolkenform dargestellte Zielmodellebene/Konfigurationsentität.\n</li><li><strong>derive</strong>: Breiter, abgewinkelter Richtungspfeil von der Entität „Design“ zur Entität „Configuration“, oberhalb des Pfeils horizontal beschriftet mit „derive“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Unidirektionaler Transformationsprozess („derive“): Die Inhalte des Designmodells werden vollständig in das Konfigurationsmodell überführt. Das Durchstreichen des Ausgangsmodells verdeutlicht, dass nach Durchführung des Ableitungsschritts kein separates Design-Artefakt weitergepflegt wird, sondern dieses vollständig in der Zielkonfiguration aufgeht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodischer Hinweis für Modellierungs- und Tooling-Workflows in AUTOSAR Adaptive: Werkzeuge und Entwickler müssen sicherstellen, dass bei dieser Strategie sämtliche designrelevanten Informationen lückenlos in die Konfigurationsmodellierung übertragen werden, da keine parallele Pflege von Design- und Konfigurationsartefakten vorgesehen ist.</p>"}], "trans": [{"from": "FIG-e80088ba3601a5fc", "to": "FIG-168ebc0d6cef6bc2", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Schreibweise der Beschriftung der Zielwolke korrigiert: von „Configration“ zu „Configuration“.\n</li><li>Beschriftung des Ableitungspfeils geändert: von gebogenem Text in gemischter Groß-/Kleinschreibung „Derive“ zu horizontal ausgerichtetem Text in Kleinschreibung „derive“.\n</li><li>Grafische Überarbeitung: Das rote Auskreuzungs-Symbol über der Design-Wolke wurde von einer gestrichelten Konturlinie auf ein halbtransparentes, durchgehend gefülltes rotes Kreuz umgestellt; der Pfeil und die Wolkenkonturen wurden neu gerendert.\n</li></ul>"}]};
